# Validate inputs
if any(arr.size == 0 for arr in [logp_with_result, logp_call_only, logp_no_call]):
    raise ValueError("Inputs must not be empty")
if not all(isinstance(x, np.ndarray) for x in [logp_with_result, logp_call_only, logp_no_call]):
    raise ValueError("All inputs must be numpy arrays")
for arr in [logp_with_result, logp_call_only, logp_no_call]:
    if arr.ndim != 2:
        raise ValueError("All inputs must be 2-dimensional")
if not (logp_with_result.shape == logp_call_only.shape == logp_no_call.shape):
    raise ValueError("All input shapes must match")
if not all(np.isfinite(arr).all() for arr in [logp_with_result, logp_call_only, logp_no_call]):
    raise ValueError("All input values must be finite")
if not all((arr <= 0).all() for arr in [logp_with_result, logp_call_only, logp_no_call]):
    raise ValueError("All input values must be nonpositive")
if isinstance(tau_filter, bool):
    raise ValueError("tau_filter cannot be boolean")
if not np.isfinite(tau_filter):
    raise ValueError("tau_filter must be finite")
if tau_filter < 0:
    raise ValueError("tau_filter must be nonnegative")

# Compute margins
margins = (logp_with_result - logp_no_call).sum(axis=1)
keep = margins > tau_filter
return keep, margins
